function identify(h){
  h=(h||'').trim();
  var res={value:h, length:h.length, charset:'', types:[]};
  if(!h) return res;
  var hex=/^[0-9a-fA-F]+$/.test(h); var b64ok=/^[A-Za-z0-9+/=]+$/.test(h);
  res.charset = hex? 'hex' : (b64ok? 'base64' : 'other');
  var L=h.length;
  var LOWER=h.toLowerCase();
  if(LOWER.indexOf('$2a$')===0||LOWER.indexOf('$2b$')===0||LOWER.indexOf('$2y$')===0) res.types.push('bcrypt');
  else if(LOWER.indexOf('$argon2')===0) res.types.push('argon2');
  else if(LOWER.indexOf('$1$')===0) res.types.push('md5-crypt');
  else if(LOWER.indexOf('$5$')===0) res.types.push('sha256-crypt');
  else if(LOWER.indexOf('$6$')===0) res.types.push('sha512-crypt');
  else if(LOWER.indexOf('scrypt$')===0) res.types.push('scrypt');
  else if(hex){
    if(L===32) res.types.push('MD5');
    else if(L===40) res.types.push('SHA-1');
    else if(L===56) res.types.push('SHA-224');
    else if(L===64) res.types.push('SHA-256');
    else if(L===96) res.types.push('SHA-384');
    else if(L===128) res.types.push('SHA-512');
  }
  if(res.types.length===0) res.types.push('unknown');
  return res;
}
var EXPORTS={identify:identify};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HashIdentifierForgePure = EXPORTS; }
